function validate([nums, lower, upper]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is an integer between -10^9 and 10^9.';
  if (![lower, upper].every(v => Number.isInteger(v) && v >= -1000000000 && v <= 1000000000)) return 'lower and upper are integers between -10^9 and 10^9.';
  if (lower > upper) return 'lower must not exceed upper.';
  return null;
}

