function countFairPairs(nums, lower, upper) {
  nums.sort((a, b) => a - b);

  const countAtMost = (limit) => {
    let count = 0;
    let left = 0;
    let right = nums.length - 1;
    while (left < right) {
      if (nums[left] + nums[right] <= limit) {
        count += right - left;
        left++;
      } else {
        right--;
      }
    }
    return count;
  };

  return countAtMost(upper) - countAtMost(lower - 1);
}

