function countFairPairs(nums, lower, upper) {
  let pairs = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const sum = nums[i] + nums[j];
      if (lower <= sum && sum <= upper) pairs++;
    }
  }
  return pairs;
}

