function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const span = size === 'large' || rand() < 0.15 ? 1000000000 : 10;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  // Bounds near the typical pair sum keep the count away from 0 and from all pairs.
  const reach = Math.min(1000000000, 2 * span);
  let lower = Math.floor(rand() * (2 * reach + 1)) - reach;
  let upper = Math.floor(rand() * (2 * reach + 1)) - reach;
  if (lower > upper) [lower, upper] = [upper, lower];
  return [nums, lower, upper];
}
